     1	const WEEKDAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
     2	const MONTH_SHORT_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
     3	
     4	/** Local-calendar date at midnight for the current browser day. */
     5	export function startOfToday(): Date {
     6	  const now = new Date();
     7	  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
     8	}
     9	
    10	export function addDays(date: Date, days: number): Date {
    11	  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
    12	}
    13	
    14	/** Formats a date as `YYYY-MM-DD` using its local calendar fields. */
    15	export function toIsoDate(date: Date): string {
    16	  const year = String(date.getFullYear()).padStart(4, '0');
    17	  const month = String(date.getMonth() + 1).padStart(2, '0');
    18	  const day = String(date.getDate()).padStart(2, '0');
    19	  return `${year}-${month}-${day}`;
    20	}
    21	
    22	/** Parses a `YYYY-MM-DD` string into a local date at midnight. */
    23	export function isoToDate(iso: string): Date {
    24	  const [year, month, day] = iso.split('-').map(Number);
    25	  return new Date(year, month - 1, day);
    26	}
    27	
    28	/** True for a well-formed ISO date that exists in the calendar (e.g. not 2026-02-30). */
    29	export function isValidIsoDate(value: string | null): value is string {
    30	  if (value === null || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    31	    return false;
    32	  }
    33	  return toIsoDate(isoToDate(value)) === value;
    34	}
    35	
    36	export function weekdayName(date: Date): string {
    37	  return WEEKDAY_NAMES[date.getDay()];
    38	}
    39	
    40	/** The show date as `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
    41	export function formatShowDate(isoDate: string, time: string): string {
    42	  const date = isoToDate(isoDate);
    43	  return `${weekdayName(date)} ${date.getDate()} ${MONTH_SHORT_NAMES[date.getMonth()]} ${time}`;
    44	}
