     1	import { inject, Injectable, signal } from '@angular/core';
     2	import { CanActivateFn, Router } from '@angular/router';
     3	
     4	/** The values typed into the checkout form. */
     5	export interface CheckoutValues {
     6	  firstName: string;
     7	  lastName: string;
     8	  email: string;
     9	  confirmEmail: string;
    10	  phone: string;
    11	  terms: boolean;
    12	}
    13	
    14	/**
    15	 * The booking in progress: the screening, the identifiers of the selected seats (a couch has two),
    16	 * the checkout values, and the customer's email once the booking is paid.
    17	 */
    18	export interface Booking {
    19	  screeningId: number;
    20	  seats: string[];
    21	  checkout: CheckoutValues;
    22	  paidEmail?: string;
    23	}
    24	
    25	export const EMPTY_CHECKOUT: CheckoutValues = {
    26	  firstName: '',
    27	  lastName: '',
    28	  email: '',
    29	  confirmEmail: '',
    30	  phone: '',
    31	  terms: false,
    32	};
    33	
    34	const STORAGE_KEY = 'cinescope.booking';
    35	
    36	/** Holds the booking in progress and keeps it in `sessionStorage`, so it survives a reload. */
    37	@Injectable({ providedIn: 'root' })
    38	export class BookingStore {
    39	  private readonly current = signal<Booking | null>(readStoredBooking());
    40	
    41	  readonly booking = this.current.asReadonly();
    42	
    43	  /** Starts an empty booking for the screening, unless a booking in progress already belongs to it. */
    44	  openFor(screeningId: number): void {
    45	    const booking = this.current();
    46	    if (booking === null || booking.screeningId !== screeningId || booking.paidEmail !== undefined) {
    47	      this.save({ screeningId, seats: [], checkout: EMPTY_CHECKOUT });
    48	    }
    49	  }
    50	
    51	  setSeats(seats: string[]): void {
    52	    this.update({ seats });
    53	  }
    54	
    55	  setCheckout(checkout: CheckoutValues): void {
    56	    this.update({ checkout });
    57	  }
    58	
    59	  /** Marks the booking in progress as paid, keeping the customer's email for the confirmation. */
    60	  markPaid(email: string): void {
    61	    this.update({ paidEmail: email });
    62	  }
    63	
    64	  clear(): void {
    65	    this.current.set(null);
    66	    sessionStorage.removeItem(STORAGE_KEY);
    67	  }
    68	
    69	  private update(changes: Partial<Booking>): void {
    70	    const booking = this.current();
    71	    if (booking !== null) {
    72	      this.save({ ...booking, ...changes });
    73	    }
    74	  }
    75	
    76	  private save(booking: Booking): void {
    77	    this.current.set(booking);
    78	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    79	  }
    80	}
    81	
    82	/**
    83	 * Lets a route with an `id` parameter be entered only with an unpaid booking in progress for that
    84	 * screening that has at least one seat; otherwise redirects to the movie list.
    85	 */
    86	export const bookingGuard: CanActivateFn = (route) => {
    87	  const booking = inject(BookingStore).booking();
    88	  const screeningId = Number(route.paramMap.get('id'));
    89	  const allowed =
    90	    booking !== null &&
    91	    booking.paidEmail === undefined &&
    92	    booking.screeningId === screeningId &&
    93	    booking.seats.length > 0;
    94	  return allowed ? true : inject(Router).createUrlTree(['/']);
    95	};
    96	
    97	/** Lets the confirmation be entered only with a paid booking; otherwise redirects to the movie list. */
    98	export const paidBookingGuard: CanActivateFn = () => {
    99	  const booking = inject(BookingStore).booking();
   100	  return booking?.paidEmail !== undefined ? true : inject(Router).createUrlTree(['/']);
   101	};
   102	
   103	function readStoredBooking(): Booking | null {
   104	  try {
   105	    const stored: unknown = JSON.parse(sessionStorage.getItem(STORAGE_KEY) ?? 'null');
   106	    return isBooking(stored) ? stored : null;
   107	  } catch {
   108	    return null;
   109	  }
   110	}
   111	
   112	function isBooking(value: unknown): value is Booking {
   113	  if (typeof value !== 'object' || value === null) {
   114	    return false;
   115	  }
   116	  const { screeningId, seats, checkout, paidEmail } = value as Partial<Record<keyof Booking, unknown>>;
   117	  return (
   118	    typeof screeningId === 'number' &&
   119	    Array.isArray(seats) &&
   120	    seats.every((id) => typeof id === 'string') &&
   121	    isCheckoutValues(checkout) &&
   122	    (paidEmail === undefined || typeof paidEmail === 'string')
   123	  );
   124	}
   125	
   126	function isCheckoutValues(value: unknown): value is CheckoutValues {
   127	  if (typeof value !== 'object' || value === null) {
   128	    return false;
   129	  }
   130	  const values = value as Record<keyof CheckoutValues, unknown>;
   131	  return (
   132	    typeof values.firstName === 'string' &&
   133	    typeof values.lastName === 'string' &&
   134	    typeof values.email === 'string' &&
   135	    typeof values.confirmEmail === 'string' &&
   136	    typeof values.phone === 'string' &&
   137	    typeof values.terms === 'boolean'
   138	  );
   139	}
=== booking/tickets.ts
     1	import { seatIdentifier } from '../seat-selection/auditorium';
     2	
     3	const COUCH_ROW = 15;
     4	const COUCH_PRICE = 89;
     5	
     6	/** One line of the booking: a single seat, or a couch covering two adjacent columns of row 15. */
     7	export type Ticket =
     8	  | { kind: 'seat'; row: number; column: number }
     9	  | { kind: 'couch'; row: number; start: number; end: number };
    10	
    11	/** The tickets of a booking, ordered by row and then by column. */
    12	export function ticketsFor(seats: readonly string[]): Ticket[] {
    13	  const positions = seats
    14	    .map((id) => {
    15	      const [row, column] = id.slice(1).split('C').map(Number);
    16	      return { row, column };
    17	    })
    18	    .sort((a, b) => a.row - b.row || a.column - b.column);
    19	
    20	  const tickets: Ticket[] = [];
    21	  for (const { row, column } of positions) {
    22	    if (row !== COUCH_ROW) {
    23	      tickets.push({ kind: 'seat', row, column });
    24	    } else if (column % 2 === 1) {
    25	      // Row 15 holds only couches, which start at an odd column; the second identifier of each is skipped.
    26	      tickets.push({ kind: 'couch', row, start: column, end: column + 1 });
    27	    }
    28	  }
    29	  return tickets;
    30	}
    31	
    32	/** The seat identifiers a ticket occupies: one for a seat, two for a couch. */
    33	export function identifiersOfTicket(ticket: Ticket): string[] {
    34	  return ticket.kind === 'seat'
    35	    ? [seatIdentifier(ticket.row, ticket.column)]
    36	    : [seatIdentifier(ticket.row, ticket.start), seatIdentifier(ticket.row, ticket.end)];
    37	}
    38	
    39	/** The seat description: the column of a seat, `Couch <a>-<b>` for a couch. */
    40	export function describeTicket(ticket: Ticket): string {
    41	  return ticket.kind === 'seat' ? String(ticket.column) : `Couch ${ticket.start}-${ticket.end}`;
    42	}
    43	
    44	/** The price in PLN: by row for a seat, per couch for a couch. */
    45	export function priceOf(ticket: Ticket): number {
    46	  if (ticket.kind === 'couch') {
    47	    return COUCH_PRICE;
    48	  }
    49	  if (ticket.row <= 5) {
    50	    return 25;
    51	  }
    52	  if (ticket.row <= 10) {
    53	    return 32;
    54	  }
    55	  return 39;
    56	}
    57	
    58	/** The total price of a booking in PLN. */
    59	export function totalOf(seats: readonly string[]): number {
    60	  return ticketsFor(seats).reduce((sum, ticket) => sum + priceOf(ticket), 0);
    61	}
    62	
    63	/** Formats an amount in PLN with two decimals, e.g. `25.00 PLN`. */
    64	export function formatPrice(amount: number): string {
    65	  return `${amount.toFixed(2)} PLN`;
    66	}
