    10	import { addDays, isoToDate, isValidIsoDate, startOfToday, toIsoDate, weekdayName } from '../dates';
    11	import { Movie, Screening } from '../models';
    12	
    13	interface DayOption {
    14	  iso: string;
    15	  label: string;
    16	}
    17	
    18	interface MovieCard {
