    29	export class MovieList {
    30	  private readonly api = inject(CinemaApi);
    31	  private readonly router = inject(Router);
    32	  private readonly route = inject(ActivatedRoute);
    33	
    34	  protected readonly today = startOfToday();
    35	  protected readonly todayIso = toIsoDate(this.today);
    36	
    37	  protected readonly days: DayOption[] = Array.from({ length: 5 }, (_, index) => {
    38	    const date = addDays(this.today, index);
    39	    return { iso: toIsoDate(date), label: index === 0 ? 'Today' : weekdayName(date) };
    40	  });
    41	
    42	  private readonly query = toSignal(this.route.queryParamMap, { requireSync: true });
    43	
    44	  /** The selected day: the `date` query parameter when it is a valid ISO date not before today, otherwise today. */
    45	  protected readonly selectedIso = computed(() => {
    46	    const requested = this.query().get('date');
    47	    return isValidIsoDate(requested) && requested >= this.todayIso ? requested : this.todayIso;
    48	  });
    49	
    50	  protected readonly pickerValue = computed(() => isoToDate(this.selectedIso()));
    51	
    52	  protected readonly data = resource({
    53	    params: () => this.selectedIso(),
    54	    loader: ({ params: date }) =>
    55	      firstValueFrom(
    56	        forkJoin({
    57	          movies: this.api.getMovies(),
    58	          screenings: this.api.getScreenings(date),
    59	        }),
    60	      ),
    61	  });
    62	
    63	  protected readonly cards = computed<MovieCard[]>(() => {
    64	    const data = this.data.value();
    65	    if (!data) {
    66	      return [];
    67	    }
    68	    return data.movies.flatMap((movie) => {
    69	      const screenings = data.screenings
    70	        .filter((screening) => screening.movieId === movie.id)
    71	        .sort((a, b) => a.time.localeCompare(b.time));
    72	      return screenings.length > 0 ? [{ movie, screenings }] : [];
    73	    });
    74	  });
    75	
    76	  constructor() {
    77	    // Replace an invalid or past `date` in the URL with the day that is actually shown.
    78	    effect(() => {
    79	      const requested = this.query().get('date');
    80	      const selected = this.selectedIso();
    81	      if (requested !== null && requested !== selected) {
    82	        void this.router.navigate([], { relativeTo: this.route, queryParams: { date: selected }, replaceUrl: true });
    83	      }
    84	    });
    85	  }
    86	
    87	  protected selectDay(iso: string): void {
    88	    void this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
    89	  }
    90	
    91	  protected onDatePicked(date: Date | null): void {
    92	    if (date !== null) {
    93	      this.selectDay(toIsoDate(date));
    94	    }
    95	  }
    96	}
