     1	export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';
     2	
     3	export interface SeatItem {
     4	  kind: 'seat';
     5	  row: number;
     6	  column: number;
     7	  state: SeatState;
     8	}
     9	
    10	export interface CouchItem {
    11	  kind: 'couch';
    12	  row: number;
    13	  start: number;
    14	  end: number;
    15	  state: SeatState;
    16	}
    17	
    18	export type AuditoriumItem = SeatItem | CouchItem;
    19	
    20	/** One row of the auditorium: the three blocks between the two aisles, left to right. */
    21	export interface AuditoriumRow {
    22	  number: number;
    23	  blocks: AuditoriumItem[][];
    24	}
