    26	const ROW_COUNT = 15;
    27	const COUCH_ROW = 15;
    28	/** Rows 1 to 10 have no seats in columns 1 to 4: the entrance. */
    29	const ENTRANCE_LAST_ROW = 10;
    30	const ACCESSIBLE_ROW = 1;
    31	const ACCESSIBLE_FIRST_COLUMN = 10;
    32	const ACCESSIBLE_LAST_COLUMN = 15;
    33	
    34	export function seatIdentifier(row: number, column: number): string {
    35	  return `R${row}C${column}`;
    36	}
    37	
    38	/** The seat identifiers an item occupies: one for a seat, two for a couch. */
    39	export function identifiersOf(item: AuditoriumItem): string[] {
    40	  return item.kind === 'seat'
    41	    ? [seatIdentifier(item.row, item.column)]
    42	    : [seatIdentifier(item.row, item.start), seatIdentifier(item.row, item.end)];
    43	}
    44	
    45	/** The seat description used in the selected-seats panel: the column, or `<a>-<b>` for a couch. */
    46	export function seatLabel(item: AuditoriumItem): string {
    47	  return item.kind === 'seat' ? String(item.column) : `${item.start}-${item.end}`;
    48	}
    49	
    50	/**
    51	 * Builds the auditorium: rows 1 to 15, each split into blocks of columns 1–4, 5–20 and 21–24.
    52	 * An item is unavailable when any of its identifiers is occupied, selected when all of its
    53	 * identifiers are in `selectedSeats`.
    54	 */
    55	export function buildAuditorium(
    56	  occupiedSeats: ReadonlySet<string>,
    57	  selectedSeats: ReadonlySet<string>,
    58	): AuditoriumRow[] {
    59	  return Array.from({ length: ROW_COUNT }, (_, index) => {
    60	    const number = index + 1;
    61	    const left = number <= ENTRANCE_LAST_ROW ? [] : itemsFor(number, 1, 4, occupiedSeats, selectedSeats);
    62	    return {
    63	      number,
    64	      blocks: [
    65	        left,
    66	        itemsFor(number, 5, 20, occupiedSeats, selectedSeats),
    67	        itemsFor(number, 21, 24, occupiedSeats, selectedSeats),
    68	      ],
    69	    };
    70	  });
    71	}
    72	
    73	function itemsFor(
    74	  row: number,
    75	  firstColumn: number,
    76	  lastColumn: number,
    77	  occupied: ReadonlySet<string>,
    78	  selected: ReadonlySet<string>,
    79	): AuditoriumItem[] {
    80	  const items: AuditoriumItem[] = [];
    81	  if (row === COUCH_ROW) {
    82	    for (let start = firstColumn; start <= lastColumn; start += 2) {
    83	      const end = start + 1;
    84	      const state = stateOf([seatIdentifier(row, start), seatIdentifier(row, end)], false, occupied, selected);
    85	      items.push({ kind: 'couch', row, start, end, state });
    86	    }
    87	    return items;
    88	  }
    89	  for (let column = firstColumn; column <= lastColumn; column++) {
    90	    const isAccessible =
    91	      row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
    92	    const state = stateOf([seatIdentifier(row, column)], isAccessible, occupied, selected);
    93	    items.push({ kind: 'seat', row, column, state });
    94	  }
    95	  return items;
    96	}
    97	
    98	function stateOf(
    99	  identifiers: readonly string[],
   100	  accessible: boolean,
   101	  occupied: ReadonlySet<string>,
   102	  selected: ReadonlySet<string>,
   103	): SeatState {
   104	  if (identifiers.some((id) => occupied.has(id))) {
   105	    return 'unavailable';
   106	  }
   107	  if (identifiers.every((id) => selected.has(id))) {
   108	    return 'selected';
   109	  }
   110	  return accessible ? 'accessible' : 'available';
   111	}
